import React, {useState, useEffect} from 'react'
import content from '../content';

function Art({src, pal}) {

    const [isShown, setIsShown] = useState(false);
    const [{page},dispatch] = useDataLayerValue();



    const contentPage = () => {
        dispatch({
          type: "SET_PAGE",
          page: "content",
        });
    }

    return (
        <div>

            <div 
            className={"mx-4"}
            onMouseEnter={() => setIsShown(true)}
            onMouseLeave={() => setIsShown(false)}
            onClick={contentPage}
            >

                <div className={`${ isShown ? "invisible" : "visible"} absolute transition-all duration-1000 ease-out `}>  
                {pal.map((color, index) => {
                    return (
                        <div key={index} Style={"background-color: " + color} className={"w-6 h-8 mx-2 visible"} ></div>
                    );
                })}
                </div>
                <div Style={isShown ? "transform: scaleX(24); transform: scaleY(24);" : ""} className={`${ isShown ? "" : "hidden" } transition-all  duration-700 ease-out h-48 w-4 bg-black`}>
                    <img className={` object-contain `} src={src} ></img>
                </div>
            </div>
        </div>
    )
}

export default Art;
